parameters.jsCode:
const trigger = $('Telegram Trigger').first().json;
const userId = String(trigger.message.from.id).trim();
const sesiones = $('Get row(s) in sheet').all().map(i => i.json).filter(r => r && r.telegram_user !== undefined && String(r.telegram_user) !== '');
const sesion = sesiones.find(r => String(r.telegram_user).trim() === userId) || null;
const usuarios = $('Get USUARIOS').all().map(i => i.json).filter(r => r && r.telegram_user !== undefined && String(r.telegram_user) !== '');
const usuario = usuarios.find(r => String(r.telegram_user).trim() === userId) || null;
function esVerdadero(v){ const s = String(v === undefined || v === null ? '' : v).trim().toLowerCase(); return s === 'si' || s === 'true' || s === '1' || s === 'x' || s === 'yes' || s === 'verdadero'; }
const existeUsuario = !!usuario;
const permitido = existeUsuario && esVerdadero(usuario.permitido) ? 'si' : 'no';
const rol = usuario && usuario.rol ? String(usuario.rol).trim().toLowerCase() : '';
const nombre = usuario && usuario.nombre ? String(usuario.nombre).trim() : '';
const pantalla = sesion && sesion.pantalla_actual ? String(sesion.pantalla_actual) : 'menu_principal';
const paso = sesion && sesion.paso_actual !== undefined && String(sesion.paso_actual) !== '' ? String(sesion.paso_actual) : '0';
const datos = sesion && sesion.datos_parciales ? String(sesion.datos_parciales) : '{}';
const esNuevo = sesion ? 'no' : 'si';
return [{ json: { telegram_user: userId, pantalla_actual: pantalla, paso_actual: paso, datos_parciales: datos, es_nuevo: esNuevo, existe_usuario: existeUsuario ? 'si' : 'no', permitido, rol, nombre } }];

// ===== Cerebro Agenda: consultar / cancelar / completar / reprogramar =====
const sesion = $('Normalizar sesion').first().json;
const trigger = $('Telegram Trigger').first().json;
const texto = String((trigger.message && trigger.message.text) || '').trim();
const userId = String(trigger.message.from.id);
const paso = String(sesion.paso_actual || 'menu');
let datos = {};
try { datos = JSON.parse(sesion.datos_parciales || '{}'); } catch (e) { datos = {}; }

const citas = $input.all().map(i => i.json).filter(r => r && r.id_cita);
const misCitas = citas.filter(c => String(c.creado_por) === userId);

function esFecha(v){ return /^\d{4}-\d{2}-\d{2}$/.test(v); }
function esHora(v){ return /^([01]\d|2[0-3]):[0-5]\d$/.test(v); }
function fechaValida(v){ return DateTime.fromFormat(v, 'yyyy-LL-dd').isValid; }
function esPasada(v){ return DateTime.fromFormat(v, 'yyyy-LL-dd').startOf('day') < $now.startOf('day'); }
function estadoLower(c){ return String(c.estado || '').toLowerCase(); }
function ordenar(arr){ return arr.slice().sort(function(a,b){ const fa=String(a.fecha||''); const fb=String(b.fecha||''); if(fa<fb) return -1; if(fa>fb) return 1; const ha=String(a.hora||''); const hb=String(b.hora||''); if(ha<hb) return -1; if(ha>hb) return 1; return 0; }); }

const menuAgendaTxt = 'Menú de Agenda:\n1. Agendar una nueva cita\n2. Consultar tu agenda\n3. Reprogramar una cita\n4. Cancelar una cita\n5. Marcar una cita como completada\n9. Volver al menú principal';

let reply = '';
let nuevaPantalla = 'agenda';
let nuevoPaso = 'menu';
let nuevosDatos = {};
let accion = 'none';
let resultado = '';
let cita = null; // fila destino a actualizar

const subflujos = ['cancelar_sel','cancelar_confirm','completar_sel','completar_confirm','reprogramar_sel','reprogramar_fecha','reprogramar_hora','reprogramar_confirm'];

function pintarLista(arr){ let l=''; for(let i=0;i<arr.length;i++){ const c=arr[i]; l += '🆔 ' + c.id_cita + '\n   📅 ' + (c.fecha||'-') + ' 🕐 ' + (c.hora||'-') + '\n   👤 ' + (c.nombre||'-') + ' 📌 ' + (c.motivo||'-') + '\n   💬 ' + (c.canal||'-') + ' | estado: ' + (c.estado||'-') + '\n\n'; } return l; }

if (texto === '9') {
  nuevaPantalla = 'agenda'; nuevoPaso = 'menu'; nuevosDatos = {};
  reply = 'Sin problema, volvemos al menú de Agenda 👍\n\n' + menuAgendaTxt;
  resultado = 'cancelo subflujo agenda';
} else if (subflujos.indexOf(paso) === -1) {
  if (texto === '2') {
    const orden = ordenar(misCitas);
    if (orden.length === 0) {
      reply = 'Aún no tienes citas guardadas 🗓️\n\nCuando agendes una (opción 1), aquí la verás.\n\n' + menuAgendaTxt;
    } else {
      reply = '🗓️ Tu agenda (' + orden.length + ' cita' + (orden.length===1?'':'s') + '):\n\n' + pintarLista(orden) + 'Escribe 9 para volver al menú principal.';
    }
    nuevoPaso = 'menu'; resultado = 'consulto agenda';
  } else if (texto === '4') {
    const cancelables = ordenar(misCitas.filter(c => estadoLower(c) !== 'cancelada' && estadoLower(c) !== 'completada'));
    if (cancelables.length === 0) {
      reply = 'No tienes citas activas para cancelar 🙂\n\n' + menuAgendaTxt; nuevoPaso = 'menu'; resultado = 'cancelar sin citas';
    } else {
      reply = '❌ Cancelar una cita\n\nEstas son tus citas activas:\n\n' + pintarLista(cancelables) + 'Escribe el 🆔 id_cita que deseas cancelar (por ejemplo: ' + cancelables[0].id_cita + ').\n\nEscribe 9 para volver al menú principal.';
      nuevoPaso = 'cancelar_sel'; resultado = 'inicio cancelar cita';
    }
  } else if (texto === '5') {
    const pend = ordenar(misCitas.filter(c => estadoLower(c) !== 'cancelada' && estadoLower(c) !== 'completada'));
    if (pend.length === 0) {
      reply = 'No tienes citas pendientes para marcar como completadas 🙂\n\n' + menuAgendaTxt; nuevoPaso = 'menu'; resultado = 'completar sin citas';
    } else {
      reply = '✅ Marcar cita como completada\n\nTus citas pendientes:\n\n' + pintarLista(pend) + 'Escribe el 🆔 id_cita que ya se realizó (por ejemplo: ' + pend[0].id_cita + ').\n\nEscribe 9 para volver al menú principal.';
      nuevoPaso = 'completar_sel'; resultado = 'inicio completar cita';
    }
  } else if (texto === '3') {
    const repro = ordenar(misCitas.filter(c => estadoLower(c) !== 'cancelada' && estadoLower(c) !== 'completada'));
    if (repro.length === 0) {
      reply = 'No tienes citas activas para reprogramar 🙂\n\n' + menuAgendaTxt; nuevoPaso = 'menu'; resultado = 'reprogramar sin citas';
    } else {
      reply = '🔄 Reprogramar una cita\n\nTus citas activas:\n\n' + pintarLista(repro) + 'Escribe el 🆔 id_cita que deseas reprogramar (por ejemplo: ' + repro[0].id_cita + ').\n\nEscribe 9 para volver al menú principal.';
      nuevoPaso = 'reprogramar_sel'; resultado = 'inicio reprogramar cita';
    }
  } else {
    reply = 'Ups, esa opción no existe en el menú de Agenda 😅\n\n' + menuAgendaTxt; nuevoPaso = 'menu'; resultado = 'opcion invalida agenda';
  }
} else {
  const modo = paso.indexOf('cancelar') === 0 ? 'cancelar' : (paso.indexOf('completar') === 0 ? 'completar' : 'reprogramar');
  const etiqueta = modo === 'cancelar' ? 'cancelar' : (modo === 'completar' ? 'completar' : 'reprogramar');

  function buscarCita(id){ return misCitas.find(c => String(c.id_cita) === String(id)) || null; }

  if (paso === 'cancelar_sel' || paso === 'completar_sel' || paso === 'reprogramar_sel') {
    const encontrada = buscarCita(texto);
    if (!encontrada) {
      reply = 'No encontré una cita con ese id que sea tuya 😕\n\nRevisa el 🆔 id_cita e inténtalo de nuevo, o escribe 9 para volver.';
      nuevoPaso = paso; nuevosDatos = datos; resultado = 'id_cita no encontrado (' + etiqueta + ')';
    } else if (estadoLower(encontrada) === 'cancelada') {
      reply = 'Esa cita ya está cancelada ⛔\n\n' + menuAgendaTxt; nuevoPaso = 'menu'; resultado = 'cita ya cancelada';
    } else if (estadoLower(encontrada) === 'completada') {
      reply = 'Esa cita ya está marcada como completada ✅\n\n' + menuAgendaTxt; nuevoPaso = 'menu'; resultado = 'cita ya completada';
    } else {
      datos = { id_cita: encontrada.id_cita, fecha: encontrada.fecha, hora: encontrada.hora, nombre: encontrada.nombre, motivo: encontrada.motivo, canal: encontrada.canal, estado: encontrada.estado, creado_por: encontrada.creado_por, timestamp_creacion: encontrada.timestamp_creacion };
      if (modo === 'reprogramar') {
        nuevoPaso = 'reprogramar_fecha'; nuevosDatos = datos;
        reply = '🔄 Reprogramar: ' + encontrada.id_cita + '\n📅 Actual: ' + encontrada.fecha + ' 🕐 ' + encontrada.hora + '\n\nEscribe la NUEVA fecha en formato AAAA-MM-DD (ejemplo: 2026-08-20).\n\nEscribe 9 para volver al menú principal.';
        resultado = 'reprogramar: cita elegida';
      } else {
        nuevoPaso = modo + '_confirm'; nuevosDatos = datos;
        const verbo = modo === 'cancelar' ? 'CANCELAR' : 'marcar como COMPLETADA';
        reply = 'Vas a ' + verbo + ' esta cita:\n\n' + pintarLista([encontrada]) + '¿Confirmas? Escribe *si* para confirmar o *no* para volver.';
        resultado = etiqueta + ': cita elegida, pido confirmacion';
      }
    }
  } else if (paso === 'cancelar_confirm' || paso === 'completar_confirm') {
    const t = texto.toLowerCase();
    if (t === 'si' || t === 'sí' || t === 's') {
      accion = 'update';
      const nuevoEstado = paso === 'cancelar_confirm' ? 'cancelada' : 'completada';
      cita = { id_cita: datos.id_cita, fecha: datos.fecha, hora: datos.hora, nombre: datos.nombre, motivo: datos.motivo, canal: datos.canal, estado: nuevoEstado, creado_por: datos.creado_por, timestamp_creacion: datos.timestamp_creacion };
      nuevoPaso = 'menu'; nuevosDatos = {};
      reply = (nuevoEstado === 'cancelada' ? '🗑️ Cita cancelada correctamente.' : '✅ ¡Cita marcada como completada!') + '\n\n🆔 ' + datos.id_cita + '\n📅 ' + datos.fecha + ' 🕐 ' + datos.hora + '\n👤 ' + datos.nombre + '\n\n' + menuAgendaTxt;
      resultado = 'cita ' + nuevoEstado + ' ' + datos.id_cita;
    } else if (t === 'no' || t === 'n') {
      nuevoPaso = 'menu'; nuevosDatos = {};
      reply = 'Perfecto, no cambié nada 👍\n\n' + menuAgendaTxt; resultado = 'confirmacion negada (' + etiqueta + ')';
    } else {
      nuevoPaso = paso; nuevosDatos = datos;
      reply = 'No te entendí 🙂 Escribe *si* para confirmar o *no* para volver.'; resultado = 'confirmacion invalida (' + etiqueta + ')';
    }
  } else if (paso === 'reprogramar_fecha') {
    if (!esFecha(texto) || !fechaValida(texto)) {
      reply = 'Esa fecha no es válida 😅\nEscríbela en formato AAAA-MM-DD (ejemplo: 2026-08-20).\n\nEscribe 9 para volver al menú principal.';
      nuevoPaso = 'reprogramar_fecha'; nuevosDatos = datos; resultado = 'reprogramar fecha invalida';
    } else if (esPasada(texto)) {
      reply = 'Esa fecha ya pasó ⏪\nElige una fecha de hoy en adelante (AAAA-MM-DD).\n\nEscribe 9 para volver al menú principal.';
      nuevoPaso = 'reprogramar_fecha'; nuevosDatos = datos; resultado = 'reprogramar fecha pasada';
    } else {
      datos.fecha = texto; nuevoPaso = 'reprogramar_hora'; nuevosDatos = datos;
      reply = 'Perfecto ✅\n\nAhora escribe la NUEVA hora en formato de 24 horas HH:MM (ejemplo: 14:30).\n\nEscribe 9 para volver al menú principal.';
      resultado = 'reprogramar fecha ok';
    }
  } else if (paso === 'reprogramar_hora') {
    if (!esHora(texto)) {
      reply = 'Esa hora no es válida 😅\nEscríbela en formato de 24 horas HH:MM (ejemplo: 09:00 o 16:45).\n\nEscribe 9 para volver al menú principal.';
      nuevoPaso = 'reprogramar_hora'; nuevosDatos = datos; resultado = 'reprogramar hora invalida';
    } else {
      const choque = misCitas.some(c => String(c.id_cita) !== String(datos.id_cita) && String(c.fecha) === datos.fecha && String(c.hora) === texto && estadoLower(c) !== 'cancelada' && estadoLower(c) !== 'completada');
      if (choque) {
        reply = 'Ya tienes otra cita el ' + datos.fecha + ' a las ' + texto + ' ⛔\nPara evitar choques, elige otra hora (HH:MM).\n\nEscribe 9 para volver al menú principal.';
        nuevoPaso = 'reprogramar_hora'; nuevosDatos = datos; resultado = 'reprogramar choque horario';
      } else {
        datos.hora = texto; nuevoPaso = 'reprogramar_confirm'; nuevosDatos = datos;
        reply = 'Revisa el cambio antes de guardar 📝\n\n🆔 ' + datos.id_cita + '\n📅 Nueva fecha: ' + datos.fecha + '\n🕐 Nueva hora: ' + datos.hora + '\n👤 ' + datos.nombre + '\n\n¿Confirmas? Escribe *si* para guardar o *no* para volver.';
        resultado = 'reprogramar hora ok, pido confirmacion';
      }
    }
  } else if (paso === 'reprogramar_confirm') {
    const t = texto.toLowerCase();
    if (t === 'si' || t === 'sí' || t === 's') {
      accion = 'update';
      cita = { id_cita: datos.id_cita, fecha: datos.fecha, hora: datos.hora, nombre: datos.nombre, motivo: datos.motivo, canal: datos.canal, estado: datos.estado || 'pendiente', creado_por: datos.creado_por, timestamp_creacion: datos.timestamp_creacion };
      nuevoPaso = 'menu'; nuevosDatos = {};
      reply = '🔄 ¡Cita reprogramada!\n\n🆔 ' + datos.id_cita + '\n📅 ' + datos.fecha + ' 🕐 ' + datos.hora + '\n👤 ' + datos.nombre + '\n\n' + menuAgendaTxt;
      resultado = 'cita reprogramada ' + datos.id_cita;
    } else if (t === 'no' || t === 'n') {
      nuevoPaso = 'menu'; nuevosDatos = {};
      reply = 'Perfecto, no cambié nada 👍\n\n' + menuAgendaTxt; resultado = 'reprogramar confirmacion negada';
    } else {
      nuevoPaso = 'reprogramar_confirm'; nuevosDatos = datos;
      reply = 'No te entendí 🙂 Escribe *si* para guardar o *no* para volver.'; resultado = 'reprogramar confirmacion invalida';
    }
  } else {
    nuevoPaso = 'menu'; nuevosDatos = {};
    reply = 'Reinicié el menú de Agenda 🔄\n\n' + menuAgendaTxt; resultado = 'reinicio agenda';
  }
}

const c = cita || {};
return [{ json: {
  reply,
  nueva_pantalla: nuevaPantalla,
  nuevo_paso: String(nuevoPaso),
  nuevos_datos: JSON.stringify(nuevosDatos || {}),
  accion,
  resultado,
  opcion: texto,
  usuario_de_telegram: userId,
  id_cita: c.id_cita || '',
  fecha: c.fecha || '',
  hora: c.hora || '',
  nombre: c.nombre || '',
  motivo: c.motivo || '',
  canal: c.canal || '',
  estado: c.estado || '',
  creado_por: c.creado_por || userId,
  timestamp_creacion: c.timestamp_creacion || ''
} }];

const trigger = $('Telegram Trigger').first().json;
const userId = String(trigger.message.from.id);
const menuPrincipal = '0. Ayuda
1. Agenda
2. Tareas
3. Recordatorios
4. Hábitos
5. Listas
6. Reportes
7. Configuración
8. Administrador';
const reply = 'Ups, algo no funcionó de mi lado 😅 Te devolví al menú principal, intenta de nuevo.

' + menuPrincipal;
return [{ json: { reply, nueva_pantalla: 'menu_principal', nuevo_paso: '0', nuevos_datos: '{}', usuario_de_telegram: userId } }];

// ===== Asistente guiado "Nueva Cita" (6 pasos) =====
const sesion = $('Normalizar sesion').first().json;
const paso = String(sesion.paso_actual || '1');
let datos = {};
try { datos = JSON.parse(sesion.datos_parciales || '{}'); } catch (e) { datos = {}; }

const trigger = $('Telegram Trigger').first().json;
const texto = String((trigger.message && trigger.message.text) || '').trim();
const userId = String(trigger.message.from.id);

const citas = $input.all().map(i => i.json).filter(r => r && r.id_cita);

function esFecha(v){ return /^\d{4}-\d{2}-\d{2}$/.test(v); }
function esHora(v){ return /^([01]\d|2[0-3]):[0-5]\d$/.test(v); }
function fechaValida(v){ return DateTime.fromFormat(v, 'yyyy-LL-dd').isValid; }
function esPasada(v){ return DateTime.fromFormat(v, 'yyyy-LL-dd').startOf('day') < $now.startOf('day'); }

const menuAgendaTxt = 'Volviste al menú de Agenda:\n1. Agendar una nueva cita\n2. Consultar tu agenda\n3. Reprogramar una cita\n4. Cancelar una cita\n5. Marcar una cita como completada\n9. Volver al menú principal';

let reply = '';
let nuevaPantalla = 'agenda_nueva_cita';
let nuevoPaso = paso;
let guardar = false;
let resultado = '';
let cita = null;

if (texto === '9') {
  nuevaPantalla = 'agenda'; nuevoPaso = '0'; datos = {};
  reply = 'Cancelaste la creación de la cita. No se guardó nada. 👍\n\n' + menuAgendaTxt;
  resultado = 'cancelo asistente nueva cita';
} else if (paso === '1') {
  if (!esFecha(texto) || !fechaValida(texto)) {
    reply = 'Esa fecha no es válida. 😅\n\nEscríbela en formato AAAA-MM-DD (ejemplo: 2026-08-15).\n\nPaso 1 de 6: Fecha\nEscribe 9 para cancelar.';
    resultado = 'fecha invalida';
  } else if (esPasada(texto)) {
    reply = 'Esa fecha ya pasó. ⏪\n\nElige una fecha de hoy en adelante (AAAA-MM-DD).\n\nPaso 1 de 6: Fecha\nEscribe 9 para cancelar.';
    resultado = 'fecha pasada';
  } else {
    datos.fecha = texto; nuevoPaso = '2';
    reply = 'Perfecto ✅\n\nPaso 2 de 6: Hora\nEscribe la hora en formato de 24 horas HH:MM (ejemplo: 14:30).\n\nEscribe 9 para cancelar.';
    resultado = 'fecha ok';
  }
} else if (paso === '2') {
  if (!esHora(texto)) {
    reply = 'Esa hora no es válida. 😅\n\nEscríbela en formato de 24 horas HH:MM (ejemplo: 09:00 o 16:45).\n\nPaso 2 de 6: Hora\nEscribe 9 para cancelar.';
    resultado = 'hora invalida';
  } else {
    datos.hora = texto; nuevoPaso = '3';
    reply = 'Genial ✅\n\nPaso 3 de 6: Nombre\nEscribe el nombre completo del cliente.\n\nEscribe 9 para cancelar.';
    resultado = 'hora ok';
  }
} else if (paso === '3') {
  if (texto.length < 2) {
    reply = 'Necesito un nombre válido. 🙂\n\nEscribe el nombre completo del cliente.\n\nPaso 3 de 6: Nombre\nEscribe 9 para cancelar.';
    resultado = 'nombre invalido';
  } else {
    datos.nombre = texto; nuevoPaso = '4';
    reply = 'Anotado ✅\n\nPaso 4 de 6: Motivo\nEscribe una breve descripción del motivo de la cita.\n\nEscribe 9 para cancelar.';
    resultado = 'nombre ok';
  }
} else if (paso === '4') {
  if (texto.length < 2) {
    reply = 'Necesito un motivo válido. 🙂\n\nEscribe una breve descripción del motivo.\n\nPaso 4 de 6: Motivo\nEscribe 9 para cancelar.';
    resultado = 'motivo invalido';
  } else {
    datos.motivo = texto; nuevoPaso = '5';
    reply = 'Listo ✅\n\nPaso 5 de 6: Canal\n¿Cómo será la cita? Escribe el número:\n1. Presencial\n2. Virtual\n3. Llamada\n\nEscribe 9 para cancelar.';
    resultado = 'motivo ok';
  }
} else if (paso === '5') {
  const canales = { '1': 'Presencial', '2': 'Virtual', '3': 'Llamada' };
  if (!canales[texto]) {
    reply = 'Esa opción de canal no existe. 😅\n\nEscribe 1 (Presencial), 2 (Virtual) o 3 (Llamada).\n\nPaso 5 de 6: Canal\nEscribe 9 para cancelar.';
    resultado = 'canal invalido';
  } else {
    datos.canal = canales[texto]; nuevoPaso = '6';
    reply = 'Revisemos tu cita antes de guardar 📝\n\n📅 Fecha: ' + datos.fecha + '\n🕐 Hora: ' + datos.hora + '\n👤 Nombre: ' + datos.nombre + '\n📌 Motivo: ' + datos.motivo + '\n💬 Canal: ' + datos.canal + '\n\nPaso 6 de 6: Confirmación\n1. Confirmar y guardar\n2. Editar (empezar de nuevo)\n3. Cancelar';
    resultado = 'canal ok, esperando confirmacion';
  }
} else if (paso === '6') {
  if (texto === '2') {
    datos = {}; nuevoPaso = '1';
    reply = 'Sin problema, empecemos de nuevo. 🔄\n\nPaso 1 de 6: Fecha\nEscribe la fecha en formato AAAA-MM-DD.\n\nEscribe 9 para cancelar.';
    resultado = 'edito, reinicio asistente';
  } else if (texto === '3') {
    nuevaPantalla = 'agenda'; nuevoPaso = '0'; datos = {};
    reply = 'Cancelaste la creación de la cita. No se guardó nada. 👍\n\n' + menuAgendaTxt;
    resultado = 'cancelo en confirmacion';
  } else if (texto === '1') {
    const choque = citas.some(c => String(c.fecha) === datos.fecha && String(c.hora) === datos.hora && String(c.estado || '').toLowerCase() !== 'cancelada');
    if (choque) {
      nuevoPaso = '6';
      reply = 'Ya existe una cita para el ' + datos.fecha + ' a las ' + datos.hora + '. ⛔\n\nPara evitar reservas dobles no puedo guardarla.\n\n¿Qué deseas hacer?\n2. Editar (cambiar fecha u hora)\n3. Cancelar';
      resultado = 'doble reserva evitada';
    } else {
      guardar = true;
      const id = 'CITA-' + $now.toFormat('yyyyLLddHHmmss');
      cita = { id_cita: id, fecha: datos.fecha, hora: datos.hora, nombre: datos.nombre, motivo: datos.motivo, canal: datos.canal, estado: 'pendiente', creado_por: userId, marca_tiempo: $now.toISO() };
      nuevaPantalla = 'agenda'; nuevoPaso = '0';
      reply = '¡Tu cita quedó agendada! 🎉\n\n🆔 ID: ' + id + '\n📅 ' + datos.fecha + ' a las ' + datos.hora + '\n👤 ' + datos.nombre + '\n📌 ' + datos.motivo + '\n💬 ' + datos.canal + '\n\n' + menuAgendaTxt;
      resultado = 'cita guardada ' + id;
      datos = {};
    }
