function estadoLower(v){ return String(v || '').toLowerCase(); }

function construirReporteUsuarios(){
  // Base = todos los usuarios registrados, as\u00ed los sin citas/tareas aparecen en cero.
  const filas = usuarios.map(u => {
    const uid = String(u.telegram_user).trim();
    const nombre = (u.nombre && String(u.nombre).trim()) ? String(u.nombre).trim() : uid;
    const cUser = citas.filter(c => String(c.creado_por) === uid);
    const tUser = tareas.filter(t => String(t.creado_por) === uid);
    const lUser = logs.filter(l => String(l.telegram_user) === uid);
    return {
      telegram_user: uid,
      nombre: nombre,
      total_citas: cUser.length,
      citas_completadas: cUser.filter(c => estadoLower(c.estado) === 'completada').length,
      citas_canceladas: cUser.filter(c => estadoLower(c.estado) === 'cancelada').length,
      total_tareas: tUser.length,
      tareas_completadas: tUser.filter(t => estadoLower(t.estado) === 'completada').length,
      tareas_pendientes: tUser.filter(t => estadoLower(t.estado) !== 'completada').length,
      interacciones: lUser.length
    };
  });
  filas.sort((a, b) => a.telegram_user < b.telegram_user ? -1 : (a.telegram_user > b.telegram_user ? 1 : 0));
  return filas;
}

