return out;

// 1. Obtener los datos completos de las hojas
const citas = $('Get_CITAS_Prod').all().map(i => i.json);
const tareas = $('Get_TAREAS_Prod').all().map(i => i.json);
const logs = $('Get_LOGS_Prod').all().map(i => i.json);

// 2. Identificar al usuario exacto que está escribiendo en Telegram
const myUserId = String($('Telegram Trigger').item.json.message.from.id).trim();

// 3. Filtrar solo los datos que coincidan con el ID de este usuario
const misCitas = citas.filter(c => String(c.telegram_user).trim() === myUserId);
const misTareas = tareas.filter(t => String(t.telegram_user).trim() === myUserId);
const misLogs = logs.filter(l => String(l.telegram_user).trim() === myUserId);

// 4. Calcular estados de Citas
let citas_completadas = misCitas.filter(c => String(c.estado || '').toLowerCase() === 'completada').length;
let citas_canceladas = misCitas.filter(c => String(c.estado || '').toLowerCase() === 'cancelada').length;

// 5. Calcular estados de Tareas
let tareas_hechas = misTareas.filter(t => ['completada', 'hecha'].includes(String(t.estado || '').toLowerCase())).length;
let tareas_pendientes = misTareas.filter(t => String(t.estado || '').toLowerCase() === 'pendiente').length;

// 6. Construir el mensaje final personalizado
let resultString = "📊 Tu Reporte Personal de Productividad\n\n";
resultString += `📅 Citas: ${misCitas.length} (Completadas: ${citas_completadas} | Canceladas: ${citas_canceladas})\n`;
resultString += `📝 Tareas: ${misTareas.length} (Hechas: ${tareas_hechas} | Pendientes: ${tareas_pendientes})\n`;
resultString += `🤖 Tus interacciones con el bot: ${misLogs.length}\n\n`;
resultString += `¿Qué deseas hacer ahora?\n1. Volver al menú Reportes\n2. Volver al menú principal`;

return [{ 
    json: { 
        text: resultString, 
        chatId: $('Telegram Trigger').item.json.message.chat.id, 
        telegram_user: myUserId 
    } 
}];
